const input = $input.first().json;
const query = input.query ?? input;

const esc = (value) => String(value).replace(/'/g, `''`);
const search = query.search ? String(query.search).trim() : null;
const page = parseInt(query.page, 10) || 1;
const limit = parseInt(query.limit, 10) || 25;
const offset = (page - 1) * limit;

return [{ json: {
  search_sql: search ? `'%${esc(search)}%'` : 'NULL',
  limit,
  offset,
} }];

const body = $input.first().json.body ?? $input.first().json;

const esc = (value) => String(value).replace(/'/g, `''`);
const sqlText = (value) => (value == null || value === '' ? 'NULL' : `'${esc(value)}'`);
const assertUuid = (value, field) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)) {
    throw new Error(`Invalid ${field}: ${value}`);
  }
  return text;
};
const makeUuid = () => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
    const rand = (Math.random() * 16) | 0;
    const value = char === 'x' ? rand : (rand & 0x3) | 0x8;
    return value.toString(16);
  });
};

const name = String(body.name ?? '').trim();
if (!name) throw new Error('name is required');
const contentHtml = String(body.content_html ?? '').trim();
if (!contentHtml) throw new Error('content_html is required');

const id = body.id ? assertUuid(body.id, 'id') : makeUuid();
const isActive = body.is_active === false ? false : true;

return [{ json: {
  id,
  id_sql: `'${esc(id)}'::uuid`,
  name_sql: sqlText(name),
  description_sql: sqlText(body.description),
  content_html_sql: sqlText(contentHtml),
  is_active_sql: isActive ? 'TRUE' : 'FALSE',
} }];

const body = $input.first().json.body ?? $input.first().json;
const id = String(body.id ?? '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
  throw new Error('Valid id is required');
}
return [{ json: { id } }];

